style.css:
/* Фон всей страницы */
body {
    background: url("https://i.ibb.co/0r9dX8z/cemetery-bg.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
    color: #dcdcdc !important;
    font-family: "Creepster", "Times New Roman", serif !important;
}

/* Полупрозрачные блоки */
div, section, header, footer {
    background-color: rgba(0, 0, 0, 0.7) !important;
    border: 1px solid #444 !important;
    border-radius: 10px !important;
}

/* Ссылки */
a {
    color: #9e3b3b !important;
    text-shadow: 0 0 5px #ff0000 !important;
    transition: 0.3s;
}

a:hover {
    color: #ff5555 !important;
    text-shadow: 0 0 15px #ff0000 !important;
}

/* Заголовки */
h1, h2, h3, h4 {
    color: #b0b0b0 !important;
    text-shadow: 2px 2px 5px black !important;
}

/* Кнопки */
button {
    background: #1a1a1a !important;
    color: #dcdcdc !important;
    border: 1px solid #666 !important;
    border-radius: 5px !important;
    transition: 0.3s;
}

button:hover {
    background: #333 !important;
    color: #ff5555 !important;
    border-color: #ff0000 !important;
}
